import Foundation

/// Pure helpers that turn a video's `subtitles`/`automaticCaptions` maps
/// into the flat language picker the options card shows. Mirrors
/// `FormatSelection`'s "reduce yt-dlp's raw lists to what the picker needs"
/// shape.
enum SubtitleSelection {

    /// One selectable subtitle language: its yt-dlp language code and
    /// whether it's auto-generated. Sites like YouTube can offer dozens of
    /// auto-translated languages alongside a handful of manually-authored
    /// ones, so auto entries are labeled rather than mixed in unmarked.
    struct LanguageOption: Identifiable, Hashable {
        let code: String
        let isAutoGenerated: Bool

        var id: String { code }

        var label: String {
            let name = Locale.current.localizedString(forLanguageCode: code) ?? code
            return isAutoGenerated ? "\(name) (auto)" : name
        }
    }

    /// Every language available: manually-authored tracks first, then
    /// auto-generated tracks for any language that has no manual track —
    /// so the same language never appears twice, and a manual track (more
    /// accurate than an auto-generated one) is always preferred when both exist.
    static func languageOptions(
        subtitles: [String: [SubtitleTrackInfo]]?,
        automaticCaptions: [String: [SubtitleTrackInfo]]?
    ) -> [LanguageOption] {
        let manualCodes = Set((subtitles ?? [:]).keys)
        let autoCodes = Set((automaticCaptions ?? [:]).keys).subtracting(manualCodes)

        let manual = manualCodes.map { LanguageOption(code: $0, isAutoGenerated: false) }
        let auto = autoCodes.map { LanguageOption(code: $0, isAutoGenerated: true) }

        return manual.sorted(by: byLabel) + auto.sorted(by: byLabel)
    }

    private static func byLabel(_ a: LanguageOption, _ b: LanguageOption) -> Bool {
        a.label.localizedCaseInsensitiveCompare(b.label) == .orderedAscending
    }
}
